'use client'

import { useEffect } from 'react'
import { useRouter } from 'next/navigation'

export default function Home() {
  const router = useRouter()

  useEffect(() => {
    // Bloquear el scroll del documento mientras se muestra el splash.
    // En iOS, sin esto, la pantalla "rebota" y deja scrollear arriba/abajo.
    const html = document.documentElement
    const body = document.body
    const prevHtml = html.style.overflow
    const prevBody = body.style.overflow
    html.style.overflow = 'hidden'
    body.style.overflow = 'hidden'

    const t = setTimeout(() => router.replace('/login'), 2600)
    return () => {
      clearTimeout(t)
      html.style.overflow = prevHtml
      body.style.overflow = prevBody
    }
  }, [router])

  const burbujas = [
    { left: '14%', size: 7,  delay: '0s',   dur: '3.2s' },
    { left: '28%', size: 5,  delay: '0.9s', dur: '2.7s' },
    { left: '46%', size: 10, delay: '0.4s', dur: '3.9s' },
    { left: '62%', size: 6,  delay: '1.3s', dur: '2.9s' },
    { left: '76%', size: 8,  delay: '0.6s', dur: '3.5s' },
    { left: '88%', size: 4,  delay: '1.7s', dur: '2.5s' },
  ]

  return (
    <div className="bm-splash">
      <img className="bm-splash-bg" src="data:image/jpeg;base64," alt="BlueMarket" />

      <div className="bm-bubbles">
        {burbujas.map((b, i) => (
          <span key={i} className="bm-bubble" style={{
            left: b.left, width: b.size, height: b.size,
            animationDelay: b.delay, animationDuration: b.dur,
          }} />
        ))}
      </div>

      <div className="bm-splash-footer">
        <div className="bm-loadbar"><div className="bm-loadbar-fill" /></div>
        <span className="bm-loading-text">Cargando experiencia...</span>
      </div>

      <style jsx>{`
        .bm-splash {
          position: fixed; top: 0; left: 0;
          width: 100vw;
          height: 100vh;   /* fallback */
          height: 100svh;  /* iOS: altura visible real, sin las barras de Safari */
          overflow: hidden; background: #03174a;
          display: flex; align-items: center; justify-content: center;
        }
        .bm-splash-bg {
          position: absolute; inset: 0; width: 100%; height: 100%;
          object-fit: cover; object-position: center top;
          animation: bm-fade-in 0.9s ease both;
        }
        @keyframes bm-fade-in { from { opacity: 0; } to { opacity: 1; } }
        .bm-bubbles { position: absolute; inset: 0; pointer-events: none; z-index: 2; }
        .bm-bubble {
          position: absolute; bottom: 120px; border-radius: 50%;
          background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.85), rgba(125,211,252,0.3));
          animation-name: bm-bubble-rise; animation-iteration-count: infinite;
          animation-timing-function: ease-in;
        }
        @keyframes bm-bubble-rise {
          0% { transform: translateY(0) scale(1); opacity: 0; }
          15% { opacity: 0.7; }
          100% { transform: translateY(-300px) scale(1.4); opacity: 0; }
        }
        .bm-splash-footer {
          position: absolute; bottom: 34px; left: 0; right: 0; z-index: 3;
          display: flex; flex-direction: column; align-items: center; gap: 11px;
        }
        .bm-loadbar {
          width: 130px; height: 3px; border-radius: 2px; overflow: hidden;
          background: rgba(255,255,255,0.15);
        }
        .bm-loadbar-fill {
          height: 100%; border-radius: 2px;
          background: linear-gradient(90deg, #4db8ff, #7dd3fc);
          animation: bm-load 2.6s ease-in-out forwards;
        }
        @keyframes bm-load { 0% { width: 0%; } 70% { width: 80%; } 100% { width: 100%; } }
        .bm-loading-text {
          font-size: 12px; color: rgba(255,255,255,0.7); letter-spacing: 0.4px;
          text-shadow: 0 1px 3px rgba(0,0,0,0.5);
        }
      `}</style>
    </div>
  )
}
